<section class="novel-activity">
<header class="novel-activity-heading"><p class="novel-eyebrow">Resultado · <?php echo html_escape($result['mode']); ?></p><h1><?php echo (int)$result['correct']; ?> de <?php echo (int)$result['total']; ?> acertos</h1><p><?php echo (int)$result['points']; ?> pontos · <?php echo novel_duration($result['duration']); ?> de prática</p></header>
<p><?php echo !empty($result['review'])?'Revisão concluída. Volte à missão completa para demonstrar domínio.':($result['mastered']?'Você atingiu o critério de domínio de 60%.':'Continue praticando para atingir 60% de acertos.'); ?> <?php echo $result['levelUp']?'Você avançou na jornada!':''; ?></p>
<?php if($result['achievements']): ?><aside><h2>Conquistas desbloqueadas</h2><ul><?php foreach($result['achievements'] as $achievement): ?><li><?php echo html_escape($achievement); ?></li><?php endforeach; ?></ul></aside><?php endif; ?>
<ol class="novel-feedback-list">
<?php foreach($result['rows'] as $row): ?><li><h2><?php echo nl2br(html_escape(str_replace('|',"\n",$row['question']))); ?></h2><p><strong><?php echo $row['correct']?'Acertou':'Revisar'; ?></strong> · Sua resposta: <?php echo html_escape($row['answer']); ?> · Resposta correta: <?php echo html_escape($row['expected']); ?></p><?php if($row['explanation']): ?><p><?php echo html_escape($row['explanation']); ?></p><?php endif; ?></li><?php endforeach; ?>
</ol>
<div class="novel-activity-actions"><?php if($result['correct']<$result['total']): $action=array('palavra'=>'jogarPalavra','texto'=>'jogarTexto','teste'=>'jogarTeste')[$result['mode']]; ?><a class="btn btn-primary" href="<?php echo base_url($result['mode'].'/'.$action.'/'.rawurlencode($result['group']).'?revisar='.$result['token']); ?>"><?php echo $result['mode']==='texto'?'Revisar a leitura completa':'Praticar o que errei'; ?></a><?php endif; ?><a class="btn btn-default" href="<?php echo base_url($result['mode']); ?>">Outras missões</a><a class="btn btn-link" href="<?php echo base_url('historia'); ?>">Ver minha história</a></div>
</section>
